import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        new Main().solve();
    }

    private void solve() {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        int a1 = in.nextInt();
        int a2 = in.nextInt();
        int a3 = in.nextInt();
        int b1 = in.nextInt();
        int b2 = in.nextInt();
        int b3 = in.nextInt();
        int max = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        int min = Math.min(a1, b1 + b3) + Math.min(a2, b1 + b2) + Math.min(a3, b2 + b3);
        min = n - min;
        out.println(min + " " + max);
        out.close();
    }
}
